import {GOAT,GOAT_SHELTERS,GOAT_REWARDS,GOAT_LEDGER_TYPES} from './goat-config.js';
import {goatPrice} from './goat-market-policy.js';
/** Transaction coherence at import/save and engine boundaries. @param {import('./engine.js').State} state */
export function validateGoatEconomy(state){const g=state.goat,entries=(/** @type {string} */type)=>state.ledger.filter(l=>l.type===type),check=(/** @type {boolean} */ok)=>{if(!ok)throw Error('Goat economy mismatch');};const rewardRows=state.ledger.filter(l=>l.type==='mission_reward'&&l.id.includes(':goat.'));check(rewardRows.every(l=>Object.keys(GOAT_REWARDS).some(id=>l.id.endsWith(':'+id))));if(!g?.visited){check(!rewardRows.length&&!state.ledger.some(l=>GOAT_LEDGER_TYPES.includes(l.type)));return;}
 const starter=entries('goat_starter_grant');check(starter.length===1&&starter[0].id===g.starterGrantId&&starter[0].amount===0);for(const goat of g.herd.filter(h=>h.id.startsWith('goat.starter.')))check(goat.acquiredTick===starter[0].tick);
 const ownedHours=state.tick-starter[0].tick,epsilon=.0001,maxHerd=GOAT_SHELTERS.at(-1)?.capacity||8;check(ownedHours>=0);check(g.stats.healthyHours<=ownedHours);check(g.stats.cleaned<=1+Math.floor(ownedHours/GOAT.cleanInterval));check(g.stats.hayUsedG+g.stats.browseUsedG<=maxHerd*GOAT.foodDayG*ownedHours/24+epsilon);check(g.stats.waterUsedMl<=maxHerd*GOAT.waterDayMl*GOAT.hotWaterFactor*ownedHours/24+epsilon);check(g.stats.restedBrowseG<=g.stats.browseUsedG+epsilon);for(const p of g.paddocks){check(p.regrownG<=GOAT.regrowthDayG*1.5*ownedHours/24+epsilon);check(p.restHours<=ownedHours);}
 const paid=(/** @type {string} */type,/** @type {number} */count,/** @type {number} */price)=>{const rows=entries(type);check(rows.length===count&&rows.every(l=>l.amount===-price));return rows;};const hay=entries('goat_feed_purchase');check(hay.length===g.stats.hayBoughtG/GOAT.hayBagG&&hay.every(l=>l.amount===-GOAT.hayBagPrice||l.amount===-24));const buys=paid('goat_purchase',g.stats.bought,GOAT.weanedPrice);for(let n=1;n<g.nextGoat;n++)check(buys.filter(l=>l.id.endsWith(':goat.bought.'+n)).length===1);
 const shelter=entries('goat_shelter_upgrade');check(shelter.length===(g.shelter?.level||0));shelter.forEach((l,i)=>check(l.amount===-GOAT_SHELTERS[i+1].price));paid('goat_paddock_purchase',g.paddocks.length-1,GOAT.paddockPrice);paid('goat_care_upgrade',g.shelter?.careUpgrade?1:0,GOAT.careUpgradePrice);
 const sales=entries('goat_sale');check(sales.length===g.sales.length);for(const sale of g.sales)check(sales.filter(l=>l.id.endsWith(':'+sale.id)&&l.tick===sale.tick&&l.amount===sale.price).length===1);
 const timeline=state.ledger.filter(l=>GOAT_LEDGER_TYPES.includes(l.type)),live=new Set(),acquired=new Map();check(timeline[0]===starter[0]);let level=0,peakHerd=0,previous=-1;for(const row of timeline){check(row.tick>=previous);previous=row.tick;if(row.type==='goat_starter_grant'){check(live.size===0);for(const id of ['goat.starter.adult','goat.starter.young.1','goat.starter.young.2']){live.add(id);acquired.set(id,row.tick);}}else{const revision=Number(row.id.split(':')[0]);check(Number.isSafeInteger(revision)&&revision>=1&&revision<=state.revision);check(row.tick>=starter[0].tick);if(row.type==='goat_purchase'){const id=row.id.slice(row.id.lastIndexOf(':')+1);check(/^goat\.bought\.[1-9][0-9]*$/.test(id)&&!acquired.has(id));live.add(id);acquired.set(id,row.tick);check(live.size<=GOAT_SHELTERS[level].capacity);}else if(row.type==='goat_shelter_upgrade'){level++;check(level<GOAT_SHELTERS.length);}else if(row.type==='goat_sale'){const id=row.id.slice(row.id.lastIndexOf(':')+1),sale=g.sales.find(s=>s.id===id);check(!!sale&&live.has(id)&&live.size>2);if(sale){check(sale.price===goatPrice(sale.condition,sale.tick));check(id==='goat.starter.adult'||sale.tick-(acquired.get(id)??Infinity)>=GOAT.growthHours);}live.delete(id);}}peakHerd=Math.max(peakHerd,live.size);}check(live.size===g.herd.length&&g.herd.every(h=>live.has(h.id)&&acquired.get(h.id)===h.acquiredTick));if(g.sales.length)check(g.stats.feedActions>0&&g.stats.waterActions>0&&g.stats.cleaned>0&&g.mission.inspectedAdult);if(g.grants.includes('goat.chapter1'))check(g.stats.sold>0);
 if(g.grants.includes('goat.healthy'))check(g.stats.healthyHours>=72);if(g.grants.includes('goat.growing'))check(g.herd.some(h=>h.id!=='goat.starter.adult'&&h.growth>=.25)||g.sales.some(h=>h.id!=='goat.starter.adult'));if(g.grants.includes('goat.pasture'))check(g.paddocks.length===2&&g.stats.rotations>=2&&g.stats.restedBrowseG>0);if(g.grants.includes('goat.bigger'))check((g.shelter?.level||0)>=1&&peakHerd>=4);if(g.grants.includes('goat.contract'))check(g.stats.sold>=2&&g.stats.bought>0);
 for(const [id,amount]of Object.entries(GOAT_REWARDS)){const rows=state.ledger.filter(l=>l.type==='mission_reward'&&l.id.endsWith(':'+id));check(rows.length===(g.grants.includes(id)?1:0)&&rows.every(l=>l.amount===amount&&Number.isSafeInteger(Number(l.id.split(':')[0]))&&Number(l.id.split(':')[0])>=1&&Number(l.id.split(':')[0])<=state.revision));}
 for(const name of /** @type {const} */(['feedActions','waterActions','cleaned','inspected','bought','sold','rotations']))check(g.stats[name]<=state.revision);check(g.stats.healthyHours<=state.tick);check(!g.mission.inspectedAdult||g.stats.inspected>0);
}
